@scope (.slide[data-layout-id="paper-ink.relationship.S1"]) {
.architecture-slot {
    position: absolute;
    left: 150px;
    width: 1620px;
    /* 眉题底边(44+2×27.3≈99) 到 caption 顶边(1080−118−行高) 之间垂直居中 */
    top: 99px;
    bottom: 166px;
    display: flex;
    align-items: center;
    z-index: 3;
  }
  .caption {
    position: absolute; left: 0; right: 0; bottom: 118px;
    text-align: center;
    font-family: var(--sans); font-weight: 400;
    font-size: var(--type-caption); letter-spacing: .04em;
    color: var(--ink);
    z-index: 5;
  }

/* Swiss Card 样式 - Adapted for square iframe preview */
.swiss-card {
  width: 600px;
  min-height: 600px;
  border-radius: 0;
  overflow: hidden;
  position: relative;
  font-family: var(--wp-font-sans);
  flex-shrink: 0;
}

.swiss-card--cover {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink);
}

.swiss-card--body {
  background: var(--wp-adapter-atlas-paper-deep);
  color: var(--wp-adapter-atlas-ink-70);
}

.swiss-card__content {
  padding: 60px;
  min-height: 600px;
  display: flex;
  flex-direction: column;
}

.swiss-card--cover .swiss-card__content {
  justify-content: center;
}

/* 标题 - 封面 */
.swiss-card h1 {
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
  color: var(--wp-adapter-atlas-ink);
}

/* H2 - 章节标题，带底部边框 */
.swiss-card h2 {
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--wp-adapter-atlas-ink-80);
  color: var(--wp-adapter-atlas-ink);
}

/* H3 */
.swiss-card h3 {
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  font-weight: 400;
  line-height: 1.3;
  margin-bottom: 16px;
  color: var(--wp-adapter-atlas-ink);
}

/* H4 */
.swiss-card h4 {
  font-family: var(--wp-font-sans);
  font-size: var(--type-body);
  font-weight: 400;
  line-height: 1.4;
  margin-bottom: 16px;
  color: var(--wp-adapter-atlas-ink);
}

/* H5 */
.swiss-card h5 {
  font-family: var(--wp-font-sans);
  font-size: var(--type-body-small);
  font-weight: 400;
  line-height: 1.4;
  margin-bottom: 12px;
  color: var(--wp-adapter-atlas-ink);
}

/* H6 */
.swiss-card h6 {
  font-family: var(--wp-font-sans);
  font-size: var(--type-body-small);
  font-weight: 400;
  line-height: 1.4;
  margin-bottom: 12px;
  color: var(--wp-adapter-atlas-ink);
}

/* 正文 */
.swiss-card p {
  font-size: var(--type-body-small);
  font-weight: 300;
  line-height: 1.8;
  margin-bottom: 16px;
  text-align: justify;
  color: var(--wp-adapter-atlas-ink-70);
}

/* 加粗 */
.swiss-card strong {
  font-weight: 400;
  color: var(--wp-adapter-atlas-ink);
}

/* 强调 */
.swiss-card em {
  font-style: italic;
  color: var(--wp-adapter-atlas-ink);
}

/* 引用 */
.swiss-card blockquote {
  margin: 32px 0;
  padding: 0 0 0 24px;
  border-left: 1px solid var(--wp-adapter-atlas-ink-80);
  font-size: var(--type-micro-secondary);
  font-weight: 300;
  line-height: 1.8;
  color: var(--wp-adapter-atlas-ink);
  letter-spacing: 0.02em;
}

.swiss-card blockquote p {
  margin-bottom: 12px;
  text-align: left;
}

.swiss-card blockquote p:last-child {
  margin-bottom: 0;
}

/* 代码块 - macOS 窗口风格 */
.swiss-card .code-block {
  background: var(--wp-adapter-atlas-paper-deep);
  border-radius: 0;
  overflow: hidden;
  margin: 24px 0;
}

.swiss-card .code-header {
  background: var(--wp-adapter-atlas-paper-deep);
  padding: 12px 16px;
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
  display: flex;
  align-items: center;
}

.swiss-card .code-dots {
  display: flex;
  gap: 8px;
}

.swiss-card .code-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}

.swiss-card .code-dot.red {
  background: var(--wp-adapter-atlas-ink-80); }
.swiss-card .code-dot.yellow {
  background: var(--wp-adapter-atlas-ink-80); }
.swiss-card .code-dot.green {
  background: var(--wp-adapter-atlas-ink-80); }

.swiss-card .code-lang {
  margin-left: auto;
  font-size: var(--type-meta);
  color: var(--wp-adapter-atlas-ink);
  font-family: var(--wp-font-mono);
}

.swiss-card pre {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink);
  padding: 16px 20px;
  margin: 0;
  font-family: var(--wp-font-mono);
  font-size: var(--type-meta);
  line-height: 1.7;
  overflow-x: auto;
  border-radius: 0;
}

.swiss-card code {
  font-family: var(--wp-font-mono);
}

.swiss-card pre code {
  background: none;
  padding: 0;
}

.swiss-card p code {
  background: var(--wp-adapter-atlas-paper-deep);
  color: var(--wp-adapter-atlas-ink-70);
  padding: 4px 12px;
  font-size: var(--type-body-small);
  border-radius: 0;
}

/* 链接 */
.swiss-card a {
  color: var(--wp-adapter-atlas-ink);
  text-decoration: none;
  border-bottom: 1px solid var(--wp-adapter-atlas-ink-80);
}

/* 列表 */
.swiss-card ul, .swiss-card ol {
  margin: 24px 0;
  padding-left: 32px;
}

.swiss-card li {
  font-size: var(--type-body-small);
  font-weight: 300;
  line-height: 1.8;
  margin-bottom: 8px;
}

.swiss-card ul li::marker {
  color: var(--wp-adapter-atlas-ink-70);
}

/* 分割线 */
.swiss-card hr {
  border: none;
  height: 0.6px;
  background: var(--wp-adapter-atlas-ink-25);
  margin: 36px 0;
  width: 80px;
  margin-left: 0;
}

/* 图片 */
.swiss-card img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 24px auto;
}

/* 表格 */
.swiss-card table {
  width: 100%;
  border-collapse: collapse;
  margin: 24px 0;
  font-size: var(--type-label);
}

.swiss-card th, .swiss-card td {
  padding: 16px 20px;
  text-align: left;
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
}

.swiss-card th {
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  background: var(--wp-adapter-atlas-paper-panel);
}

/* 极简表格样式 - 可通过 table.alt 类使用 */
.swiss-card table.alt {
  border-top: 0.6px solid var(--wp-adapter-atlas-ink-25);
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
}

.swiss-card table.alt th {
  color: var(--wp-adapter-atlas-ink);
  background: none;
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
  font-weight: 300;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-size: var(--type-label);
}

.swiss-card table.alt td {
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
}

.swiss-card table.alt tr:last-child td {
  border-bottom: none;
}

/* 封面元信息 */
.cover-meta {
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--wp-adapter-atlas-ink-45);
  margin-top: auto;
}

.cover-date {
  font-size: var(--type-meta);
  color: var(--wp-adapter-atlas-ink-45);
  margin-top: 16px;
}

/* 分隔提示 */
.divider-hint {
  text-align: center;
  color: var(--wp-adapter-atlas-ink-45);
  font-size: var(--type-meta);
  padding: 8px;
}

/* ===== PPT 布局样式 ===== */
.swiss-card .layout-grid {
  display: grid;
  gap: 20px;
  margin: 20px 0;
}

/* 2列布局 */
.swiss-card .two-col {
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

/* 3列布局 */
.swiss-card .three-col {
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

/* 左右对比布局 */
.swiss-card .vs-grid {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
}
.swiss-card .vs-grid .vs-divider {
  font-size: var(--type-body);
  color: var(--wp-adapter-atlas-ink);
  font-weight: 300;
}

/* 流程链 */
.swiss-card .process-chain {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 0;
}
.swiss-card .process-chain .step {
  flex: 1;
  text-align: center;
  padding: 16px 8px;
  background: var(--wp-adapter-atlas-paper-panel);
  border-radius: 0;
  font-size: var(--type-meta);
}
.swiss-card .process-chain .arrow {
  color: var(--wp-adapter-atlas-ink);
  font-size: var(--type-body-small);
}
.swiss-card .process-annotated-grid {
  margin: 20px 0;
  row-gap: 12px;
  align-items: start;
}
.swiss-card .process-annotated-grid--plain {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  column-gap: 12px;
  overflow: visible;
}
.swiss-card .process-annotated-grid--arrow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  column-gap: 12px;
}
.swiss-card .process-annotated-grid .step-node {
  text-align: center;
  padding: 16px 8px;
  background: var(--wp-adapter-atlas-paper-panel);
  font-size: var(--type-meta);
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.swiss-card .process-annotated-grid--plain .step-node {
  grid-row: 1;
}
.swiss-card .process-annotated-grid--plain .step-node.col-1 {
  grid-column: 1; }
.swiss-card .process-annotated-grid--plain .step-node.col-2 {
  grid-column: 2; }
.swiss-card .process-annotated-grid--plain .step-node.col-3 {
  grid-column: 3; }
.swiss-card .process-annotated-grid--plain .step-node.col-4 {
  grid-column: 4; }
.swiss-card .process-annotated-grid .step-link {
  grid-row: 1;
  align-self: center;
  justify-self: center;
  color: var(--wp-adapter-atlas-ink);
  font-size: var(--type-body-small);
  font-weight: 300;
}
.swiss-card .process-annotated-grid--plain .step-link {
  position: absolute;
  top: 26px;
  transform: translate(-50%, -50%);
}
.swiss-card .process-annotated-grid--plain .step-link.link-1 {
  left: 25%; }
.swiss-card .process-annotated-grid--plain .step-link.link-2 {
  left: 50%; }
.swiss-card .process-annotated-grid--plain .step-link.link-3 {
  left: 75%; }
.swiss-card .process-annotated-grid .caption-node {
  grid-row: 2;
  align-self: stretch;
  padding: 12px 12px 12px;
  background: var(--wp-adapter-atlas-paper-panel);
  border: 0.6px solid var(--wp-adapter-atlas-ink-25);
  border-radius: 0;
}
.swiss-card .process-annotated-grid--plain .caption-node.col-1 {
  grid-column: 1; }
.swiss-card .process-annotated-grid--plain .caption-node.col-2 {
  grid-column: 2; }
.swiss-card .process-annotated-grid--plain .caption-node.col-3 {
  grid-column: 3; }
.swiss-card .process-annotated-grid--plain .caption-node.col-4 {
  grid-column: 4; }
.swiss-card .process-annotated-grid .caption-label {
  display: block;
  margin-bottom: 8px;
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--wp-adapter-atlas-ink-45);
}
.swiss-card .process-annotated-grid .caption-node p {
  margin: 0;
  font-size: var(--type-meta);
  line-height: 1.6;
  color: var(--wp-adapter-atlas-ink-45);
}
/* 6步骤双行布局 - 顺时针环绕 */
.swiss-card .process-chain[data-type="wrap"] {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(2, auto);
  grid-template-areas: "s1 s2 s3"
        "s6 s5 s4";
  gap: 24px 32px;
  position: relative;
  padding: 12px 20px;
  overflow: visible;
}
.swiss-card .process-chain[data-type="wrap"] .step {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px 12px;
  background: var(--wp-adapter-atlas-data-5);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  font-size: var(--type-meta);
  font-weight: 300;
  text-align: center;
}
.swiss-card .process-chain[data-type="wrap"] .arrow {
  display: none;
}
/* 步骤定位 - 顺时针环绕 */
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(1) {
  grid-area: s1; }
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(3) {
  grid-area: s2; }
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(5) {
  grid-area: s3; }
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(7) {
  grid-area: s4; }
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(9) {
  grid-area: s5; }
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(11) {
  grid-area: s6; }

/* 第一行右箭头：1→2, 2→3 */
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(1)::after,
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(3)::after {
  content: '→';
  position: absolute;
  right: -26px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--wp-adapter-atlas-ink);
  font-size: var(--type-micro-secondary);
  font-weight: 300;
}
/* 3→4 向下箭头（设计→开发） */
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(5)::after {
  content: '↓';
  position: absolute;
  left: 50%;
  bottom: -26px;
  transform: translateX(-50%);
  color: var(--wp-adapter-atlas-ink);
  font-size: var(--type-micro-secondary);
  font-weight: 300;
}
/* 第二行左箭头：开发(s4)←测试(s5), 测试(s5)←上线(s6) */
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(7)::after,
.swiss-card .process-chain[data-type="wrap"] .step:nth-child(9)::after {
  content: '←';
  position: absolute;
  left: -26px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--wp-adapter-atlas-ink);
  font-size: var(--type-micro-secondary);
  font-weight: 300;
  z-index: 2;
}

/* 流程链 - 彩色箭头形状变体 */
.swiss-card .process-chain[data-type="arrow"] {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 20px 0;
}
.swiss-card .process-chain[data-type="arrow"] .arrow {
  display: none;
}
.swiss-card .process-chain[data-type="arrow"] .step {
  flex: 1;
  text-align: center;
  padding: 16px 8px;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  position: relative;
  margin-right: 8px;
  border-radius: 0;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
  white-space: nowrap;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 52px;
  overflow: hidden;
}
.swiss-card .process-chain[data-type="arrow"] .step:first-child {
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%);
  border-radius: 0;
  padding-left: 12px;
}
.swiss-card .process-chain[data-type="arrow"] .step:last-child {
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
  margin-right: 0;
  border-radius: 0;
  padding-left: 20px;
  padding-right: 20px;
}
/* 步骤颜色 - 彩虹渐变 */
.swiss-card .process-chain[data-type="arrow"] .step:nth-child(1) {
  background: var(--wp-adapter-atlas-data-4); }
.swiss-card .process-chain[data-type="arrow"] .step:nth-child(3) {
  background: var(--wp-adapter-atlas-data-5); }
.swiss-card .process-chain[data-type="arrow"] .step:nth-child(5) {
  background: var(--wp-adapter-atlas-data-5); }
.swiss-card .process-chain[data-type="arrow"] .step:nth-child(7) {
  background: var(--wp-adapter-atlas-data-4); }
.swiss-card .process-chain[data-type="arrow"] .step:nth-child(9) {
  background: var(--wp-adapter-atlas-data-1); }

/* 5步骤变体 - 缩小字体和padding以适应宽度 */
.swiss-card .process-chain[data-type="arrow"]:has(.step:nth-child(9)) .step {
  font-size: var(--type-meta);
  padding: 12px 4px;
  min-height: 44px;
}
.swiss-card .process-chain[data-type="arrow"]:has(.step:nth-child(9)) .step:first-child {
  padding-left: 8px;
}
.swiss-card .process-chain[data-type="arrow"]:has(.step:nth-child(9)) .step:last-child {
  padding-left: 12px;
  padding-right: 12px;
}
.swiss-card .process-annotated-grid--arrow .step-node {
  grid-row: 1;
  margin-right: 0;
  padding: 16px 12px;
  color: var(--wp-adapter-atlas-ink);
  font-size: var(--type-meta);
  font-weight: 300;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
  background: var(--wp-adapter-atlas-paper-panel);
}
.swiss-card .process-annotated-grid--arrow .step-node.tone-1 {
  background: var(--wp-adapter-atlas-paper-panel); }
.swiss-card .process-annotated-grid--arrow .step-node.tone-2 {
  background: var(--wp-adapter-atlas-paper-panel); }
.swiss-card .process-annotated-grid--arrow .step-node.tone-3 {
  background: var(--wp-adapter-atlas-paper-panel); }
.swiss-card .process-annotated-grid--arrow .step-node.tone-4 {
  background: var(--wp-adapter-atlas-paper-panel); }
.swiss-card .process-annotated-grid--arrow .caption-node {
  grid-row: 2;
}

/* 循环流程 */
.swiss-card .process-loop {
  display: flex;
  justify-content: center;
  gap: 20px;
  margin: 20px 0;
}
.swiss-card .process-loop .loop-item {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--wp-adapter-atlas-paper-panel);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--type-meta);
  text-align: center;
  border: 1px solid var(--wp-adapter-atlas-ink-80);
}

/* 维度矩阵 */
.swiss-card .matrix-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 16px 0;
}
.swiss-card .matrix-grid .cell {
  padding: 16px;
  background: var(--wp-adapter-atlas-paper-panel);
  border-left: 0.6px solid var(--wp-adapter-atlas-ink-25);
}
.swiss-card .matrix-grid .cell h4 {
  font-size: var(--type-body-small);
  margin-bottom: 8px;
}
.swiss-card .matrix-grid .cell p {
  font-size: var(--type-body-small);
  margin: 0;
}

/* 时间轴 - 基础样式 */
.swiss-card .timeline {
  position: relative;
  margin: 20px 0;
}

/* 竖版时间轴 - 点线在左，时间和内容在右 */
.swiss-card .timeline[data-type="vertical"] {
  padding-left: 32px;
}
.swiss-card .timeline[data-type="vertical"]::before {
  content: '';
  position: absolute;
  left: 8px;
  top: 0;
  bottom: 0;
  width: 0.8px;
  background: var(--wp-adapter-atlas-ink-80);
}
.swiss-card .timeline[data-type="vertical"] .item {
  position: relative;
  padding-bottom: 24px;
  padding-left: 24px;
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 16px;
}
.swiss-card .timeline[data-type="vertical"] .item::before {
  content: '';
  position: absolute;
  left: -26px;
  top: 6px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--wp-adapter-atlas-ink-80);
}
.swiss-card .timeline[data-type="vertical"] .item .year {
  font-size: var(--type-meta);
  color: var(--wp-adapter-atlas-ink-45);
  font-weight: 300;
  min-width: 70px;
