/* 同心层 - 圆叠加 */
.swiss-card .concentric {
  position: relative;
  height: 260px;
  margin: 12px 0;
}
.swiss-card .concentric .layer {
  position: absolute;
  left: 50%;
  border-radius: 50%;
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  background: var(--wp-adapter-atlas-paper-panel);
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  transform: translateX(-50%);
}
/* 圆环尺寸 */
.swiss-card .concentric .layer-1 {
  width: 100px;
  height: 100px;
  z-index: 3; }
.swiss-card .concentric .layer-2 {
  width: 180px;
  height: 180px;
  z-index: 2; }
.swiss-card .concentric .layer-3 {
  width: 260px;
  height: 260px;
  z-index: 1; }

/* 文字基础样式 - 水平居中 */
.swiss-card .concentric .layer-text {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
}

/* ========== 中心对齐 ========== */
/* 所有圆心重合在容器中心 */
.swiss-card .concentric.align-center .layer {
  top: 50%;
  transform: translate(-50%, -50%); }
/* 文字在各自圆环的中间位置:
 * layer-1: 在圆心 (0px 从圆心，因为是内圈中心)
 * layer-2: 在 layer-1 和 layer-2 中间 = (50+90)/2 = 70px 从圆心
 * layer-3: 在 layer-2 和 layer-3 中间 = (90+130)/2 = 110px 从圆心
 */
.swiss-card .concentric.align-center .layer-1 .layer-text {
  top: 50%;
  transform: translate(-50%, -50%); }
.swiss-card .concentric.align-center .layer-2 .layer-text {
  top: calc(50% - 70px);
  transform: translate(-50%, -50%); }
.swiss-card .concentric.align-center .layer-3 .layer-text {
  top: calc(50% - 110px);
  transform: translate(-50%, -50%); }

/* ========== 顶部对齐 ========== */
/* 圆顶对齐 */
.swiss-card .concentric.align-top .layer {
  top: 0;
  transform: translateX(-50%); }
/* 文字在各自圆环的中间:
 * layer-1: 在 100px 圆的中心 = 50px 从顶部
 * layer-2: 在 layer-1(100px) 和 layer-2(180px) 中间 = 50 + 40/2 = 70px 从顶部
 * layer-3: 在 layer-2(180px) 和 layer-3(260px) 中间 = 90 + 40/2 = 110px 从顶部
 */
.swiss-card .concentric.align-top .layer-1 .layer-text {
  top: 50px;
  transform: translate(-50%, -50%); }
.swiss-card .concentric.align-top .layer-2 .layer-text {
  top: 140px;
  transform: translate(-50%, -50%); }
.swiss-card .concentric.align-top .layer-3 .layer-text {
  top: 220px;
  transform: translate(-50%, -50%); }

/* ========== 底部对齐 ========== */
/* 圆底对齐 - 整体旋转180度，与顶部对齐对应 */
.swiss-card .concentric.align-bottom .layer {
  bottom: 0;
  top: auto;
  transform: translateX(-50%); }
/* 文字位置与顶部对齐对应（容器高260px，260-top=bottom）:
 * 顶部对齐: layer-1=50px, layer-2=140px, layer-3=220px
 * 底部对齐: layer-1=210px, layer-2=120px, layer-3=40px
 */
.swiss-card .concentric.align-bottom .layer-1 .layer-text {
  bottom: 210px;
  transform: translate(-50%, -50%);
  z-index: 10; }
.swiss-card .concentric.align-bottom .layer-2 .layer-text {
  bottom: 120px;
  transform: translate(-50%, -50%);
  z-index: 10; }
.swiss-card .concentric.align-bottom .layer-3 .layer-text {
  bottom: 40px;
  transform: translate(-50%, -50%);
  z-index: 10; }

/* ========== 中心对齐 + 文字在圆环下方 ========== */
/* 圆环中心对齐 */
.swiss-card .concentric.align-center-text-bottom .layer {
  top: 50%;
  transform: translate(-50%, -50%); }
/* 文字在各自圆环的中间位置（与变体1a相同计算，只是方向在下方）:
 * layer-1 (数据层): 在圆心正中
 * layer-2 (服务层): 在 layer-1 和 layer-2 中间 = (50+90)/2 = 70px，现在在下方
 * layer-3 (应用层): 在 layer-2 和 layer-3 中间 = (90+130)/2 = 110px，现在在下方
 */
.swiss-card .concentric.align-center-text-bottom .layer-1 .layer-text {
  top: 50%;
  transform: translate(-50%, -50%); }
.swiss-card .concentric.align-center-text-bottom .layer-2 .layer-text {
  top: calc(50% + 70px);
  transform: translate(-50%, -50%); }
.swiss-card .concentric.align-center-text-bottom .layer-3 .layer-text {
  top: calc(50% + 110px);
  transform: translate(-50%, -50%); }

/* 金字塔 - ECharts 漏斗图风格 (正三角) */
.swiss-card .pyramid {
