/* 冰山 - 单体冰山 + 外围标注 */
.swiss-card .iceberg {
  --iceberg-line: var(--wp-adapter-atlas-ink-80);
  --iceberg-top: var(--wp-adapter-atlas-ink);
  --iceberg-top-facet: var(--wp-adapter-atlas-ink);
  --iceberg-bottom: var(--wp-adapter-atlas-ink);
  --iceberg-bottom-facet: var(--wp-adapter-atlas-ink);
  display: grid;
  grid-template-columns: minmax(0, 1.24fr) minmax(0, 2.08fr) minmax(0, 1.24fr);
  align-items: center;
  gap: 16px;
  min-height: 470px;
  margin: 12px 0;
}
.swiss-card .iceberg__callout {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: max-content;
  max-width: none;
}
.swiss-card .iceberg__callout::before {
  content: '';
  position: absolute;
  top: 10px;
  width: 8px;
  height: 8px;
  background: var(--wp-adapter-atlas-ink-80);
  border-radius: 50%;
}
.swiss-card .iceberg__callout::after {
  content: '';
  position: absolute;
  top: 13px;
  width: 44px;
  height: 0.8px;
  background: var(--wp-adapter-atlas-ink-80);
}
.swiss-card .iceberg__callout strong {
  display: block;
