}
.swiss-card .iceberg__callout--surface {
  text-align: right;
  align-self: start;
  margin-top: 92px;
  justify-self: end;
  padding-right: 48px;
  transform: translateX(30%);
}
.swiss-card .iceberg__callout--surface::before {
  right: 36px;
}
.swiss-card .iceberg__callout--surface::after {
  right: 0;
}
.swiss-card .iceberg__callout--depth {
  align-self: end;
  margin-bottom: 60px;
  justify-self: start;
  padding-left: 48px;
