  height: 28px;
  transform: translateX(-50%);
  background: var(--wp-adapter-atlas-ink-80);
  pointer-events: none;
}
.swiss-card .iceberg__waterline {
  position: absolute;
  left: -12%;
  right: -12%;
  top: 41.43%;
  height: 0.8px;
  background: var(--wp-adapter-atlas-ink-80);
  z-index: 2;
}
.swiss-card .iceberg__waterline::before,
.swiss-card .iceberg__waterline::after {
  content: '';
  position: absolute;
  top: -1px;
