}
.swiss-card .venn-three .circle-b {
  background: var(--wp-adapter-atlas-paper-panel);
  border-color: var(--wp-adapter-atlas-ink-80);
  color: var(--wp-adapter-atlas-ink);
  top: 87px;
  left: calc(50% - 108px);
}
.swiss-card .venn-three .circle-c {
  background: var(--wp-adapter-atlas-paper-panel);
  border-color: var(--wp-adapter-atlas-ink-80);
  color: var(--wp-adapter-atlas-ink);
  top: 87px;
  left: calc(50% - 12px);
}

/* 思维导图 - SVG 覆盖层绘线 */
.swiss-card .mind-map {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 0;
  position: relative;
  transform-origin: center top;
}
.swiss-card .mind-map .mind-map-overlay {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: visible;
  z-index: 1;
}
.swiss-card .mind-map .mind-map-line {
  stroke: var(--wp-adapter-atlas-ink-80);
  stroke-width: 1;
  fill: none;
  stroke-linecap: square;
  vector-effect: non-scaling-stroke;
}
.swiss-card .mind-map .root-node {
  background: var(--wp-adapter-atlas-data-4);
  color: var(--wp-adapter-atlas-ink);
  padding: 16px 28px;
  border-radius: 0;
  font-weight: 400;
  font-size: var(--type-body-small);
  position: relative;
  z-index: 5;
  box-shadow: none;
}
.swiss-card .mind-map .branches {
  display: flex;
  justify-content: center;
  gap: 32px;
  width: 100%;
  margin-top: 52px;
  position: relative;
}
.swiss-card .mind-map .branch {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}
.swiss-card .mind-map .node {
  background: var(--wp-adapter-atlas-data-6);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  padding: 12px 16px;
  font-size: var(--type-meta);
  font-weight: 300;
  margin-top: 20px;
  min-width: 100px;
  text-align: center;
  position: relative;
  box-shadow: none;
  z-index: 2;
}

/* 竖版思维导图 - 左根右枝，3层结构 */
.swiss-card .mind-map[data-type="vertical"] {
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 80px;
  padding: 40px 32px;
  transform-origin: left center;
}

.swiss-card .mind-map[data-type="vertical"] .root-node {
  flex-shrink: 0;
}

.swiss-card .mind-map[data-type="vertical"] .branches {
  flex-direction: column;
  gap: 20px;
  margin-top: 0;
  align-items: flex-start;
  width: auto;
  position: relative;
}

.swiss-card .mind-map[data-type="vertical"] .branch {
  flex-direction: row;
  align-items: center;
  gap: 52px;
  position: relative;
}

.swiss-card .mind-map[data-type="vertical"] .node {
  margin-top: 0;
  width: 104px;
  min-width: 104px;
  height: 36px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* 第3层容器 */
.swiss-card .mind-map[data-type="vertical"] .sub-branches {
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  padding-left: 40px;
}

.swiss-card .mind-map[data-type="vertical"] .sub-node {
  background: var(--wp-adapter-atlas-data-6);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  width: 104px;
  min-width: 104px;
  height: 36px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--type-meta);
  font-weight: 300;
  text-align: center;
  position: relative;
  box-shadow: none;
  z-index: 2;
}

/* 架构图 - 垂直分层 */
.swiss-card .architecture {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 24px 0;
}
.swiss-card .arch-layer {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  padding: 16px;
  position: relative;
}
.swiss-card .arch-layer::after {
  content: attr(data-layer);
  position: absolute;
  right: 12px;
  top: -10px;
  background: var(--wp-adapter-atlas-ink-80);
  color: var(--wp-adapter-atlas-ink);
  padding: 4px 8px;
  font-size: var(--type-meta);
  font-weight: 300;
  text-transform: uppercase;
}
.swiss-card .arch-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
  gap: 12px;
}
.swiss-card .arch-item {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  padding: 12px 8px;
  text-align: center;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  box-shadow: none;
}

/* 引用页 - 过渡页大字 */
.swiss-card .quote-page {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: 60px;
  background: var(--wp-adapter-atlas-paper-panel);
  position: relative;
  min-height: 400px;
  width: 100%;
}
.swiss-card .quote-page::before {
  content: '"';
  position: absolute;
  top: 20px;
  left: 40px;
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  color: var(--wp-adapter-atlas-ink);
  line-height: 1;
}
.swiss-card .quote-page h1 {
  font-size: var(--type-subheading);
  line-height: 1.4;
  color: var(--wp-adapter-atlas-ink);
  margin-bottom: 32px;
  position: relative;
  z-index: 1;
}
.swiss-card .quote-page .cite {
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--wp-adapter-atlas-ink);
}

/* 多因素对比表 */
.swiss-card .comparison-table {
  width: 100%;
  border-collapse: collapse;
  margin: 20px 0;
  font-size: var(--type-meta);
  border: 0.6px solid var(--wp-adapter-atlas-ink-25);
}
.swiss-card .comparison-table th {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink);
  padding: 12px;
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.swiss-card .comparison-table td {
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
  padding: 12px;
}
.swiss-card .comparison-table tr:hover {
  background: var(--wp-adapter-atlas-paper-panel);
}
.swiss-card .comparison-table .score {
  color: var(--wp-adapter-atlas-ink);
  font-weight: 300;
  font-family: var(--wp-font-mono);
}

/* SWOT - 2x2 矩阵，Swiss Style 极简设计 */
.swiss-card .swot {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 20px 0;
  position: relative;
}
.swiss-card .swot .cell {
  padding: 24px 20px;
  font-size: var(--type-meta);
  background: var(--wp-adapter-atlas-paper-panel);
  position: relative;
  min-height: 140px;
}
/* 字母标识 - 大号衬线体 */
.swiss-card .swot .cell::before {
  position: absolute;
  top: 16px;
  right: 20px;
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  font-weight: 300;
  line-height: 1;
  opacity: 0.12;
}
.swiss-card .swot .strengths::before {
  content: 'S';
  color: var(--wp-adapter-atlas-ink); }
.swiss-card .swot .weaknesses::before {
  content: 'W';
  color: var(--wp-adapter-atlas-ink); }
.swiss-card .swot .opportunities::before {
  content: 'O';
  color: var(--wp-adapter-atlas-ink); }
.swiss-card .swot .threats::before {
  content: 'T';
  color: var(--wp-adapter-atlas-ink); }

/* 优势 - 绿色系 */
.swiss-card .swot .strengths {
  background: var(--wp-adapter-atlas-paper-panel);
  border-left: 1px solid var(--wp-adapter-atlas-ink-80);
}
.swiss-card .swot .strengths h4 {
  color: var(--wp-adapter-atlas-ink);
  font-family: var(--wp-font-sans);
}
/* 劣势 - 红色系 */
.swiss-card .swot .weaknesses {
  background: var(--wp-adapter-atlas-paper-panel);
  border-left: 1px solid var(--wp-adapter-atlas-ink-80);
}
.swiss-card .swot .weaknesses h4 {
  color: var(--wp-adapter-atlas-ink);
  font-family: var(--wp-font-sans);
}
/* 机会 - 蓝色系 */
.swiss-card .swot .opportunities {
  background: var(--wp-adapter-atlas-paper-panel);
  border-left: 1px solid var(--wp-adapter-atlas-ink-80);
}
.swiss-card .swot .opportunities h4 {
  color: var(--wp-adapter-atlas-ink);
  font-family: var(--wp-font-sans);
}
/* 威胁 - 橙黄色系 */
.swiss-card .swot .threats {
  background: var(--wp-adapter-atlas-paper-panel);
  border-left: 1px solid var(--wp-adapter-atlas-ink-80);
}
.swiss-card .swot .threats h4 {
  color: var(--wp-adapter-atlas-ink);
  font-family: var(--wp-font-sans);
}
/* 标题样式 */
.swiss-card .swot .cell h4 {
  font-size: var(--type-body-small);
  margin-bottom: 12px;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.swiss-card .swot .cell p {
  color: var(--wp-adapter-atlas-ink-70);
  line-height: 1.6;
  font-size: var(--type-body-small);
  margin: 0;
}

/* Quadrant Axis - 坐标轴象限版 */
.swiss-card .quadrant-axis {
  position: relative;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(0, 1fr));
  gap: 24px 28px;
  min-height: 360px;
  padding: 36px 28px;
  align-content: center;
}
.swiss-card .quadrant-axis::before,
.swiss-card .quadrant-axis::after {
  content: '';
  position: absolute;
  background: var(--wp-adapter-atlas-ink-25);
  opacity: 0.24;
}
.swiss-card .quadrant-axis::before {
  top: 22px;
  bottom: 22px;
  left: 50%;
  width: 0.6px;
  transform: translateX(-50%);
}
.swiss-card .quadrant-axis::after {
  left: 20px;
  right: 20px;
  top: 50%;
  height: 0.6px;
  transform: translateY(-50%);
}
.swiss-card .quadrant-axis .axis-label {
  position: absolute;
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--wp-adapter-atlas-ink-45);
}
.swiss-card .quadrant-axis .axis-label.top {
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}
.swiss-card .quadrant-axis .axis-label.bottom {
  bottom: 2px;
  left: 50%;
  transform: translateX(-50%);
}
.swiss-card .quadrant-axis .axis-label.left {
  left: 0;
  top: 50%;
  transform: translateY(-50%) rotate(-90deg);
  transform-origin: left center;
}
.swiss-card .quadrant-axis .axis-label.right {
  right: 0;
  top: 50%;
  transform: translateY(-50%) rotate(90deg);
  transform-origin: right center;
}
.swiss-card .quadrant-axis .axis-center {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 54px;
  height: 54px;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--wp-adapter-atlas-ink-25);
  color: var(--wp-adapter-atlas-ink-45);
  font-family: var(--wp-font-sans);
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  z-index: 2;
}
.swiss-card .quadrant-axis .quadrant {
  position: relative;
  z-index: 1;
  background: var(--wp-adapter-atlas-ink-25);
  padding: 16px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 112px;
}
.swiss-card .quadrant-axis .quadrant .marker {
  font-family: var(--wp-font-sans);
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.swiss-card .quadrant-axis .quadrant h4 {
  margin: 0;
  font-size: var(--type-body-small);
  line-height: 1.35;
  font-weight: 400;
  font-family: var(--wp-font-sans);
}
.swiss-card .quadrant-axis .quadrant p {
  margin: 0;
  font-size: var(--type-meta);
  line-height: 1.6;
  color: var(--wp-adapter-atlas-ink-45);
}
.swiss-card .quadrant-axis .q1 {
  color: var(--wp-adapter-atlas-ink-45); }
.swiss-card .quadrant-axis .q2 {
  color: var(--wp-adapter-atlas-ink-45); }
.swiss-card .quadrant-axis .q3 {
  color: var(--wp-adapter-atlas-ink-45); }
.swiss-card .quadrant-axis .q4 {
  color: var(--wp-adapter-atlas-ink-45); }

/* ===== 引用页 ===== */
.swiss-card .quote {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100%;
  padding: 48px 40px;
  position: relative;
  text-align: center;
}

/* 大号装饰引号 */
.swiss-card .quote::before {
  content: '"';
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  color: var(--wp-adapter-atlas-ink);
  opacity: 0.12;
  line-height: 1;
  position: absolute;
  top: 30px;
  left: 30px;
  pointer-events: none;
}

.swiss-card .quote::after {
  content: '"';
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  color: var(--wp-adapter-atlas-ink);
  opacity: 0.12;
  line-height: 1;
  position: absolute;
  bottom: 10px;
  right: 30px;
  pointer-events: none;
  transform: rotate(180deg);
}

/* 装饰分隔线 */
.swiss-card .quote .divider {
  width: 40px;
  height: 0.6px;
  background: var(--wp-adapter-atlas-ink-25);
  margin-bottom: 24px;
}

/* 引用内容 */
.swiss-card .quote blockquote {
  font-family: var(--wp-font-sans);
  font-size: var(--type-subheading);
  font-weight: 300;
  line-height: 1.7;
  color: var(--wp-adapter-atlas-ink);
  margin: 0 0 32px 0;
  padding: 0;
  border: none;
  position: relative;
  z-index: 1;
}

/* 作者信息 */
.swiss-card .quote .author {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.swiss-card .quote .author-name {
  font-size: var(--type-label);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  font-style: normal;
}

.swiss-card .quote .author-title {
  font-size: var(--type-body-small);
  color: var(--wp-adapter-atlas-ink);
  font-weight: 300;
}

/* 来源标注 */
.swiss-card .quote .source {
  margin-top: 16px;
  font-size: var(--type-meta);
  color: var(--wp-adapter-atlas-ink-45);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 300;
}

/* 前后对比 */
.swiss-card .before-after {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin: 16px 0;
}
.swiss-card .before-after .side {
  padding: 20px;
  text-align: left;
  border-radius: 0;
}
.swiss-card .before-after .before {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
}
.swiss-card .before-after .after {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
}
.swiss-card .before-after .badge {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 0;
  font-size: var(--type-meta);
  font-weight: 300;
  margin-bottom: 12px;
}
/* Before/After 默认：Before绿色，After红色 */
.swiss-card .before-after .before .badge {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink); }
.swiss-card .before-after .after .badge {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink); }

/* 变体：带箭头的 before-after（现状→目标） */
.swiss-card .before-after.with-arrow {
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
}
.swiss-card .before-after.with-arrow .arrow {
  font-size: var(--type-body);
  color: var(--wp-adapter-atlas-ink);
  font-weight: 300;
  padding: 0 12px;
}
/* 现状→目标：现状绿色，目标红色 */
.swiss-card .before-after.with-arrow .before .badge {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink); }
.swiss-card .before-after.with-arrow .after .badge {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink); }

/* 无背景色变体 */
.swiss-card .before-after.no-bg .side {
  background: transparent;
  border: 0.6px solid var(--wp-adapter-atlas-ink-25);
}
.swiss-card .before-after.no-bg .before {
  border-color: var(--wp-adapter-atlas-ink-80);
}
.swiss-card .before-after.no-bg .after {
  border-color: var(--wp-adapter-atlas-ink-80);
}
.swiss-card .before-after.no-bg .before .badge {
  background: transparent;
  color: var(--wp-adapter-atlas-ink);
  padding: 0; }
.swiss-card .before-after.no-bg .after .badge {
  background: transparent;
  color: var(--wp-adapter-atlas-ink);
  padding: 0; }

.swiss-card .before-after--verification {
  display: grid;
  gap: 12px;
  margin: 8px 0;
}

.swiss-card .before-after--verification .compare-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 18px minmax(0, 1fr);
  gap: 8px;
  align-items: stretch;
  padding: 0;
}

.swiss-card .before-after--verification .compare-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--wp-font-sans);
  font-size: var(--type-meta);
  line-height: 1;
  letter-spacing: 0.08em;
  color: var(--wp-adapter-atlas-ink);
  text-align: center;
}

.swiss-card .before-after--verification .compare-side {
  position: relative;
  min-height: 54px;
  padding: 12px 12px 8px;
  display: flex;
  align-items: center;
  font-size: var(--type-meta);
  line-height: 1.4;
  overflow-wrap: break-word;
  word-break: normal;
}

.swiss-card .before-after--verification .compare-side--fuzzy {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 0.6px solid var(--wp-adapter-atlas-ink-25);
  color: var(--wp-adapter-atlas-ink);
  text-decoration: line-through;
  text-decoration-color: var(--wp-adapter-atlas-ink);
}

.swiss-card .before-after--verification .compare-side--precise {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  box-shadow: none;
  color: var(--wp-adapter-atlas-ink);
  font-weight: 300;
}

.swiss-card .before-after--verification .compare-tag {
  position: absolute;
  left: 8px;
  top: -7px;
  padding: 4px 4px;
  font-size: var(--type-meta);
  line-height: 1;
  font-weight: 300;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.swiss-card .before-after--verification p {
  margin: 0;
}

.swiss-card .before-after--verification .compare-side--fuzzy .compare-tag {
  background: var(--wp-adapter-atlas-paper-panel);
  border: 0.6px solid var(--wp-adapter-atlas-ink-25);
  color: var(--wp-adapter-atlas-ink);
}

.swiss-card .before-after--verification .compare-side--precise .compare-tag {
  background: var(--wp-adapter-atlas-paper-panel);
  color: var(--wp-adapter-atlas-ink);
}

/* 甘特图 - 带时间轴 */
.swiss-card .gantt {
  margin: 20px 0;
}
/* 时间轴头部 */
.swiss-card .gantt-header {
  display: flex;
  margin-bottom: 8px;
  padding-bottom: 8px;
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
}
.swiss-card .gantt-header .label {
  width: 80px;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink-45);
}
.swiss-card .gantt-header .timeline {
  flex: 1;
  display: flex;
  justify-content: space-between;
  font-size: var(--type-meta);
  color: var(--wp-adapter-atlas-ink);
}
.swiss-card .gantt-header .timeline span {
  flex: 1;
  text-align: center;
  position: relative;
}
