.swiss-card .list-card-header {
  background: var(--wp-adapter-atlas-paper-deep);
  color: var(--wp-adapter-atlas-ink);
  padding: 16px 20px;
  font-family: var(--wp-font-sans);
  font-size: var(--type-meta);
  font-weight: 300;
  letter-spacing: 0.05em;
}

.swiss-card .list-card ul,
.swiss-card .list-card ol {
  list-style: none;
  padding: 0;
  margin: 0;
}

.swiss-card .list-card li {
  padding: 16px 20px;
  border-bottom: 0.6px solid var(--wp-adapter-atlas-ink-25);
  position: relative;
  font-size: var(--type-body-small);
  line-height: 1.6;
  display: flex;
  align-items: flex-start;
  gap: 12px;
