  border-bottom: none;
}

.swiss-card .list-card li:hover {
  background: var(--wp-adapter-atlas-paper-panel);
}

/* 编号样式 */
.swiss-card .list-card ol li::before {
  content: counter(list-counter, decimal-leading-zero);
  counter-increment: list-counter;
  font-family: var(--wp-font-mono);
  font-size: var(--type-body-small);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink-70);
  min-width: 24px;
  text-align: right;
}

.swiss-card .list-card ol {
  counter-reset: list-counter;
}

/* 无序列表图标 */
.swiss-card .list-card ul li::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--wp-adapter-atlas-ink-80);
  margin-top: 8px;
  flex-shrink: 0;
}

/* 层级缩进 */
.swiss-card .list-card li.level-2 {
  padding-left: 44px;
  background: var(--wp-adapter-atlas-paper-panel);
}

.swiss-card .list-card li.level-2::before {
  content: '›';
  font-size: var(--type-body-small);
  color: var(--wp-adapter-atlas-ink-70);
}

.swiss-card .list-card li.level-3 {
  padding-left: 68px;
  background: var(--wp-adapter-atlas-paper-panel);
  font-size: var(--type-body-small);
