}

/* ===== Process Loop 变体样式 ===== */
/* 三角循环 */
.swiss-card .process-loop[data-type="triangle"] {
  position: relative;
  width: 260px;
  height: 240px;
  margin: 20px auto;
}
.swiss-card .process-loop[data-type="triangle"] .loop-item {
  position: absolute;
  width: 70px;
  height: 70px;
  border-radius: 50%;
  background: var(--wp-adapter-atlas-data-4);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
}
.swiss-card .process-loop[data-type="triangle"] .loop-item:nth-child(1) {
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
}
.swiss-card .process-loop[data-type="triangle"] .loop-item:nth-child(2) {
  bottom: 20px;
  left: 20px;
}
.swiss-card .process-loop[data-type="triangle"] .loop-item:nth-child(3) {
  bottom: 20px;
  right: 20px;
}
/* 三角连接线 */
.swiss-card .process-loop[data-type="triangle"]::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 180px;
  height: 180px;
  border: 0.6px dashed var(--wp-adapter-atlas-ink-25);
  border-radius: 50%;
  transform: translate(-50%, -40%);
}

/* 四角循环 - 菱形布局（上、右、下、左） */
.swiss-card .process-loop[data-type="quad"] {
  position: relative;
  width: 240px;
  height: 240px;
  margin: 20px auto;
}
.swiss-card .process-loop[data-type="quad"] .loop-item {
  position: absolute;
  width: 70px;
  height: 70px;
  border-radius: 50%;
  background: var(--wp-adapter-atlas-data-4);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  text-align: center;
}
/* 上 */
.swiss-card .process-loop[data-type="quad"] .loop-item:nth-child(1) {
  top: 0;
  left: 50%;
  transform: translateX(-50%);
}
/* 右 */
.swiss-card .process-loop[data-type="quad"] .loop-item:nth-child(2) {
  top: 50%;
  right: 0;
  transform: translateY(-50%);
}
/* 下 */
.swiss-card .process-loop[data-type="quad"] .loop-item:nth-child(3) {
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
}
/* 左 */
.swiss-card .process-loop[data-type="quad"] .loop-item:nth-child(4) {
  top: 50%;
  left: 0;
  transform: translateY(-50%);
}
/* 四角连接线 - 虚线圆 */
.swiss-card .process-loop[data-type="quad"]::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 170px;
  height: 170px;
  border: 0.6px dashed var(--wp-adapter-atlas-ink-25);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

/* 五角循环 - 五等分圆形 */
.swiss-card .process-loop[data-type="pentagon"] {
  position: relative;
  width: 260px;
  height: 260px;
  margin: 20px auto;
}
.swiss-card .process-loop[data-type="pentagon"] .loop-item {
  position: absolute;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--wp-adapter-atlas-data-4);
  border: 1px solid var(--wp-adapter-atlas-ink-80);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--type-meta);
  font-weight: 300;
  color: var(--wp-adapter-atlas-ink);
  text-align: center;
  transform: translate(-50%, -50%);
}
/* 五等分圆形 - 精确三角函数计算，圆心在圆周上
   中心(130px,130px), 半径90px, 角度: -90°, -18°, 54°, 126°, 198° */
.swiss-card .process-loop[data-type="pentagon"] .loop-item:nth-child(1) {
  top: calc(50% - 90px);
  left: 50%; }
.swiss-card .process-loop[data-type="pentagon"] .loop-item:nth-child(2) {
  top: calc(50% - 28px);
  left: calc(50% + 86px); }
.swiss-card .process-loop[data-type="pentagon"] .loop-item:nth-child(3) {
  top: calc(50% + 73px);
  left: calc(50% + 53px); }
.swiss-card .process-loop[data-type="pentagon"] .loop-item:nth-child(4) {
  top: calc(50% + 73px);
  left: calc(50% - 53px); }
.swiss-card .process-loop[data-type="pentagon"] .loop-item:nth-child(5) {
  top: calc(50% - 28px);
  left: calc(50% - 86px); }
/* 五边形连接线 - 虚线圆 */
.swiss-card .process-loop[data-type="pentagon"]::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 180px;
  height: 180px;
  border: 0.6px dashed var(--wp-adapter-atlas-ink-25);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

